  1	//! Exec implements the logic for starting and stopping a subprocess with a
  2	//! pty as well as spinning up the necessary read thread to read from the
  3	//! pty and forward it to the Termio instance.
  4	const Exec = @This();
  5	
  6	const std = @import("std");
  7	const builtin = @import("builtin");
  8	const assert = @import("../quirks.zig").inlineAssert;
  9	const Allocator = std.mem.Allocator;
 10	const ArenaAllocator = std.heap.ArenaAllocator;
 11	const posix = std.posix;
 12	const global = @import("../global.zig");
 13	const xev = global.xev;
 14	const apprt = @import("../apprt.zig");
 15	const build_config = @import("../build_config.zig");
 16	const configpkg = @import("../config.zig");
 17	const crash = @import("../crash/main.zig");
 18	const fastmem = @import("../fastmem.zig");
 19	const internal_os = @import("../os/main.zig");
 20	const renderer = @import("../renderer.zig");
 21	const shell_integration = @import("shell_integration.zig");
 22	const terminal = @import("../terminal/main.zig");
 23	const termio = @import("../termio.zig");
 24	const Command = @import("../Command.zig");
 25	const ptypkg = @import("../pty.zig");
 26	const Pty = ptypkg.Pty;
 27	const EnvMap = std.process.Environ.Map;
 28	const PasswdEntry = internal_os.passwd.Entry;
 29	const windows = internal_os.windows;
 30	const ProcessInfo = @import("../pty.zig").ProcessInfo;
 31	const compat_fd = @import("../lib/compat/fd.zig");
 32	
 33	const log = std.log.scoped(.io_exec);
 34	
 35	/// The termios poll rate in milliseconds.
 36	const TERMIOS_POLL_MS = 200;
 37	
 38	/// If we build with flatpak support then we have to keep track of
 39	/// a potential execution on the host.
 40	const FlatpakHostCommand = if (!build_config.flatpak) struct {
 41	    pub const Completion = struct {};
 42	} else internal_os.FlatpakHostCommand;
 43	
 44	/// The subprocess state for our exec backend.
 45	subprocess: Subprocess,
 46	
 47	/// Initialize the exec state. This will NOT start it, this only sets
 48	/// up the internal state necessary to start it later.
 49	pub fn init(
 50	    alloc: Allocator,
 51	    cfg: Config,
 52	) !Exec {
 53	    var subprocess = try Subprocess.init(alloc, cfg);
 54	    errdefer subprocess.deinit();
 55	
 56	    return .{ .subprocess = subprocess };
 57	}
 58	
 59	pub fn deinit(self: *Exec) void {
 60	    self.subprocess.deinit();
 61	}
 62	
 63	/// Call to initialize the terminal state as necessary for this backend.
 64	/// This is called before any termio begins. This should not be called
 65	/// after termio begins because it may put the internal terminal state
 66	/// into a bad state.
 67	pub fn initTerminal(self: *Exec, term: *terminal.Terminal) void {
 68	    // If we have an initial pwd requested by the subprocess, then we
 69	    // set that on the terminal now. This allows rapidly initializing
 70	    // new surfaces to use the proper pwd.
 71	    if (self.subprocess.cwd) |cwd| term.setPwd(cwd) catch |err| {
 72	        log.warn("error setting initial pwd err={}", .{err});
 73	    };
 74	
 75	    // Setup our initial grid/screen size from the terminal. This
 76	    // can't fail because the pty should not exist at this point.
 77	    self.resize(.{
 78	        .columns = term.cols,
 79	        .rows = term.rows,
 80	    }, .{
 81	        .width = term.width_px,
 82	        .height = term.height_px,
 83	    }) catch unreachable;
 84	}
 85	
 86	pub fn threadEnter(
 87	    self: *Exec,
 88	    alloc: Allocator,
 89	    io: *termio.Termio,
 90	    td: *termio.Termio.ThreadData,
 91	) !void {
 92	    // Start our subprocess
 93	    const pty_fds = self.subprocess.start(alloc) catch |err| {
 94	        // If we specifically got this error then we are in the forked
 95	        // process and our child failed to execute. If we DIDN'T
 96	        // get this specific error then we're in the parent and
 97	        // we need to bubble it up.
 98	        if (err != error.ExecFailedInChild) return err;
 99	
100	        // We're in the child. Nothing more we can do but abnormal exit.
101	        // The Command will output some additional information.
102	        std.process.exit(1);
103	    };
104	    errdefer self.subprocess.stop();
105	
106	    // Watcher to detect subprocess exit
107	    var process: ?xev.Process = if (self.subprocess.process) |v| switch (v) {
108	        .fork_exec => |cmd| try xev.Process.init(
109	            cmd.pid orelse return error.ProcessNoPid,
110	        ),
111	
112	        // If we're executing via Flatpak then we can't do
113	        // traditional process watching (its implemented
114	        // as a special case in os/flatpak.zig) since the
115	        // command is on the host.
116	        .flatpak => null,
117	    } else return error.ProcessNotStarted;
118	    errdefer if (process) |*p| p.deinit();
119	
120	    // Track our process start time for abnormal exits
121	    const process_start: std.Io.Timestamp = .now(global.io(), .awake);
122	
123	    // Create our pipe that we'll use to kill our read thread.
124	    // pipe[0] is the read end, pipe[1] is the write end.
125	    const pipe = try internal_os.pipe();
126	    errdefer _ = posix.system.close(pipe[0]);
127	    errdefer _ = posix.system.close(pipe[1]);
128	
129	    // Setup our stream so that we can write.
130	    var stream = xev.Stream.initFd(pty_fds.write);
131	    errdefer stream.deinit();
132	
133	    // Start our timer to read termios state changes. This is used
134	    // to detect things such as when password input is being done
135	    // so we can render the terminal in a different way.
136	    var termios_timer = try xev.Timer.init();
137	    errdefer termios_timer.deinit();
138	
139	    // Start our read thread
140	    const read_thread = try std.Thread.spawn(
141	        .{},
142	        if (builtin.target.os.tag == .windows) ReadThread.threadMainWindows else ReadThread.threadMainPosix,
143	        .{ pty_fds.read, io, pipe[0] },
144	    );
145	    read_thread.setName(global.io(), "io-reader") catch {};
146	
147	    // Setup our threadata backend state to be our own
148	    td.backend = .{ .exec = .{
149	        .start = process_start,
150	        .write_stream = stream,
151	        .process = process,
152	        .read_thread = read_thread,
153	        .read_thread_pipe = pipe[1],
154	        .read_thread_fd = pty_fds.read,
155	        .termios_timer = termios_timer,
156	    } };
157	
158	    // Start our process watcher. If we have an xev.Process use it.
159	    if (process) |*p| p.wait(
160	        td.loop,
161	        &td.backend.exec.process_wait_c,
162	        termio.Termio.ThreadData,
163	        td,
164	        processExit,
165	    ) else if (comptime build_config.flatpak) flatpak: {
166	        switch (self.subprocess.process orelse break :flatpak) {
167	            // If we're in flatpak and we have a flatpak command
168	            // then we can run the special flatpak logic for watching.
169	            .flatpak => |*c| c.waitXev(
170	                td.loop,
171	                &td.backend.exec.flatpak_wait_c,
172	                termio.Termio.ThreadData,
173	                td,
174	                flatpakExit,
175	            ),
176	
177	            .fork_exec => {},
178	        }
179	    }
180	
181	    // Start our termios timer. We don't support this on Windows.
182	    // Fundamentally, we could support this on Windows so we're just
183	    // waiting for someone to implement it.
184	    if (comptime builtin.target.os.tag != .windows) {
185	        termios_timer.run(
186	            td.loop,
187	            &td.backend.exec.termios_timer_c,
188	            TERMIOS_POLL_MS,
189	            termio.Termio.ThreadData,
190	            td,
191	            termiosTimer,
192	        );
193	    }
194	}
195	
196	pub fn threadExit(self: *Exec, td: *termio.Termio.ThreadData) void {
197	    assert(td.backend == .exec);
198	    const exec = &td.backend.exec;
199	
200	    if (exec.exited) self.subprocess.externalExit();
201	    self.subprocess.stop();
202	
203	    // Quit our read thread after exiting the subprocess so that
204	    // we don't get stuck waiting for data to stop flowing if it is
205	    // a particularly noisy process.
206	    switch (posix.errno(posix.system.write(exec.read_thread_pipe, "x", 1))) {
207	        .SUCCESS => {},
208	
209	        // EPIPE means that our read thread is closed already, which is
210	        // completely fine since that is what we were trying to achieve.
211	        .PIPE => {},
212	
213	        else => |e| log.warn(
214	            "error writing to read thread quit pipe err=E{s}",
215	            .{@tagName(e)},
216	        ),
217	    }
218	
219	    if (comptime builtin.target.os.tag == .windows) {
220	        // Interrupt the blocking read so the thread can see the quit message
221	        if (windows.exp.kernel32.CancelIoEx(exec.read_thread_fd, null) == windows.FALSE) {
222	            switch (windows.GetLastError()) {
223	                .NOT_FOUND => {},
224	                else => |err| log.warn("error interrupting read thread err={}", .{err}),
225	            }
226	        }
227	    }
228	
229	    exec.read_thread.join();
230	}
231	
232	pub fn focusGained(
233	    self: *Exec,
234	    td: *termio.Termio.ThreadData,
235	    focused: bool,
236	) !void {
237	    _ = self;
238	
239	    assert(td.backend == .exec);
240	    const execdata = &td.backend.exec;
241	
242	    // Windows has no termios, so there is nothing to poll.
243	    if (comptime builtin.target.os.tag == .windows) return;
244	
245	    if (!focused) {
246	        // Flag the timer to end on the next iteration. This is
247	        // a lot cheaper than doing full timer cancellation.
248	        execdata.termios_timer_running = false;
249	    } else {
250	        // Always set this to true. There is a race condition if we lose
251	        // focus and regain focus before the termios timer ticks where
252	        // if we don't set this unconditionally the timer will end on
253	        // the next iteration.
254	        execdata.termios_timer_running = true;
255	
256	        // If we're focused, we want to start our termios timer. We
257	        // only do this if it isn't already running. We use the termios
258	        // callback because that'll trigger an immediate state check AND
259	        // start the timer.
260	        if (execdata.termios_timer_c.state() != .active) {
261	            _ = termiosTimer(td, undefined, undefined, {});
262	        }
263	    }
264	}
265	
266	pub fn resize(
267	    self: *Exec,
268	    grid_size: renderer.GridSize,
269	    screen_size: renderer.ScreenSize,
270	) !void {
271	    return try self.subprocess.resize(grid_size, screen_size);
272	}
273	
274	fn processExitCommon(td: *termio.Termio.ThreadData, exit_code: u32) void {
275	    assert(td.backend == .exec);
276	    const execdata = &td.backend.exec;
277	    execdata.exited = true;
278	
279	    // Determine how long the process was running for.
280	    const runtime_ms: u64 = @max(
281	        0,
282	        execdata.start.untilNow(global.io(), .awake).toMilliseconds(),
283	    );
284	    log.debug("child process exited status={} runtime={}ms", .{ exit_code, runtime_ms });
285	
286	    // We always notify the surface immediately that the child has
287	    // exited and some metadata about the exit.
288	    _ = td.surface_mailbox.push(.{
289	        .child_exited = .{
290	            .exit_code = exit_code,
291	            .runtime_ms = runtime_ms,
292	        },
293	    }, .{ .forever = {} });
294	}
295	
296	fn processExit(
297	    td_: ?*termio.Termio.ThreadData,
298	    _: *xev.Loop,
299	    _: *xev.Completion,
300	    r: xev.Process.WaitError!u32,
301	) xev.CallbackAction {
302	    const exit_code = r catch unreachable;
303	    processExitCommon(td_.?, exit_code);
304	    return .disarm;
305	}
306	
307	fn flatpakExit(
308	    td_: ?*termio.Termio.ThreadData,
309	    _: *xev.Loop,
310	    _: *FlatpakHostCommand.Completion,
311	    r: FlatpakHostCommand.WaitError!u8,
312	) void {
313	    const exit_code = r catch unreachable;
314	    processExitCommon(td_.?, exit_code);
315	}
