1756	    /// Sets the fd to non-blocking mode. Returns false on failure.
1757	    fn setNonblock(fd: posix.fd_t) bool {
1758	        const flags = posix.system.fcntl(fd, posix.F.GETFL);
1759	        if (flags == -1) {
1760	            log.warn("read thread failed to get flags err=E{s}", .{@tagName(posix.errno(-1))});
1761	            return false;
1762	        }
1763	
1764	        switch (posix.errno(posix.system.fcntl(
1765	            fd,
1766	            posix.F.SETFL,
1767	            flags | @as(u32, @bitCast(posix.O{ .NONBLOCK = true })),
1768	        ))) {
1769	            .SUCCESS => {},
1770	            else => |e| {
1771	                log.warn("read thread failed to set flags err=E{s}", .{@tagName(e)});
1772	                return false;
1773	            },
1774	        }
1775	        return true;
1776	    }
